QS=[
Q('באיזה חוק יסוד קיימת פסקת התגברות?','חופש העיסוק',['כבוד האדם וחירותו','הכנסת','הממשלה'],'פסקת ההתגברות מופיעה בס׳ 8 לחוק יסוד: חופש העיסוק בלבד. בחוק כבוד האדם אין פסקה כזו, ובחוק הכנסת והממשלה אין הוראה שמאפשרת לגבור על זכות אדם.'),
Q('מהו הרוב הנדרש לחוקק חוק בפסקת התגברות?','רוב חברי הכנסת (61 לפחות)',['רוב של 80 חברי כנסת','רוב הנוכחים בהצבעה','פה אחד'],'נדרש רוב של חברי הכנסת (61), ולא רק רוב הנוכחים. 80 נדרש בהקשרים אחרים, ופה אחד אינו נדרש כלל, ולכן שני האחרונים אינם נכונים.'),
Q('מהו תוקפו המרבי של חוק בפסקת התגברות?','ארבע שנים',['שנתיים','שש שנים','ללא הגבלה'],'החוק פוקע בתום ארבע שנים מיום קבלתו, או במועד מוקדם יותר אם נקבע כך. תוקף בלתי מוגבל סותר את תכלית הפסקה, ולכן נותר רק מספר שנים מוגבל.'),
Q('מה נדרש בנוסח החוק שנחקק בפסקת התגברות?','אמירה מפורשת שהוא תקף "על אף האמור בחוק היסוד"',['הפניה לפסיקה','חתימת הנשיא בלבד','אישור בג"ץ מראש'],'האמירה המפורשת היא תנאי להפעלת הפסקה. אין צורך באישור מוקדם של בג"ץ, חתימת הנשיא אינה תנאי מיוחד, וההפניה לפסיקה אינה תחליף.'),
Q('איזו פרשה הובילה להכנסת פסקת ההתגברות?','מיטראל (יבוא בשר)',['קול העם','בית סוריק','חורב'],'פרשת מיטראל, שבה נפסלה מדיניות מניעת יבוא בשר לא כשר, הובילה לחקיקת ס׳ 8. קול העם עוסק בביטוי, בית סוריק בגדר, וחורב בסגירת רחוב.'),
Q('איזה חוק נחקק בשימוש מובהק בפסקת ההתגברות?','חוק יבוא בשר',['חוק גל','חוק טל','חוק הלאום'],'חוק יבוא בשר הוא המקרה המובהק של שימוש. חוק גל נבחן בבנק המזרחי, חוק טל בשוויון, וחוק הלאום הוא חוק יסוד ולא חוק בפסקת התגברות.'),
Q('מה קורה לחוק שנחקק בפסקת התגברות בתום ארבע שנים?','הוא פוקע, אלא אם נחקק מחדש כדין',['הוא הופך לחוק יסוד','הוא ממשיך לתמיד','הוא נפסל מיד'],'הפקיעה אוטומטית, ולכן נדרשת חקיקה חדשה כדי להמשיך. החוק אינו הופך לחוק יסוד ואינו נפסל, והוא גם אינו מתמשך מעצמו.'),
Q('מהי "הרמוניה חקיקתית"?','פרשנות המקיימת נורמות מאותה דרגה זו לצד זו',['עדיפות חוק מאוחר תמיד','עדיפות חוק יסוד על חוק יסוד אחר','ביטול כל סתירה'],'עיקרון ההרמוניה מבקש לקיים את כל הנורמות ככל האפשר. עדיפות אוטומטית היא הכרעה חריגה, ולא ההרמוניה, ואין ביטול של סתירה.'),
Q('האם יש היררכיה בין חוקי היסוד?','לא, כולם באותה דרגה נורמטיבית',['כן, כבוד האדם עליון על כולם','כן, חוק יסוד: הכנסת עליון','כן, המאוחר עליון תמיד'],'אין היררכיה פורמלית ביניהם, וכל ההכרעות נעשות בפרשנות. טענות על עליונות כבוד האדם או הכנסת אינן מבוססות, והמאוחר אינו גובר תמיד.'),
Q('מהו ההבדל בין פסקת ההגבלה לפסקת ההתגברות?','הראשונה מתנה פגיעה כדין; השנייה מאפשרת פגיעה בלי עמידה בתנאים',['אין הבדל','הראשונה חלה רק על הכנסת','השנייה קובעת מידתיות'],'פסקת ההגבלה קובעת מתי הפגיעה כדין, ואילו ההתגברות עוקפת אותה. מידתיות שייכת להגבלה, וההגבלה אינה רק של הכנסת.'),
Q('איזה טיעון נשמע נגד פסקת ההתגברות?','שהיא מרוקנת את עליונות הזכויות',['שהיא מונעת חקיקה','שהיא נוגדת את הרוב','שהיא פוגעת בשופטים'],'הביקורת המרכזית היא שהמנגנון מאפשר לרוב לפגוע בזכויות. האחרות הפוכות או אינן קשורות.'),
Q('איזה טיעון נשמע בעד פסקת ההתגברות?','שהיא משמרת את סמכות ההכרעה האחרונה בידי נציגי העם',['שהיא מבטלת ביקורת שיפוטית','שהיא מבטלת זכויות','שהיא מונעת פסקת הגבלה'],'התומכים מדגישים את הלגיטימציה הדמוקרטית. ביטול הביקורת או הזכויות אינו הטיעון, והיא אינה מונעת את פסקת ההגבלה.'),
Q('חוק יבוא בשר בעתירה נגדו (4676/94):','נמצא תקף כי עמד בתנאי הפסקה',['נפסל כי הפגיע בקניין','נפסל בשל אי-מידתיות','בוטל בידי הכנסת'],'משעמד בתנאי הפסקה, אין בחינה מחדש של הפגיעה בחופש העיסוק. פסילה בשל אי-מידתיות היא ההפך.'),
Q('מהי ההשלכה של חוק שנחקק בהתגברות על פסקת ההגבלה?','אינו נבחן בה לעניין חופש העיסוק',['נבחן בה כרגיל','נבחן בה רק אם הוא קצר','בטל מיד'],'ההתגברות מבטלת את תחולת פסקת ההגבלה על החוק לעניין חופש העיסוק. לא נבחן כרגיל ואינו בטל.'),
Q('כאשר שני חוקי יסוד סותרים ואי אפשר ליישב ביניהם, איזה כלל פרשני מקובל?','ספציפי גובר על כללי',['כללי גובר על ספציפי','אין הכרעה','הרשות המבצעת מחליטה'],'כלל פרשני מקובל, שהספציפי גובר. הכללי אינו גובר, ויש הכרעה.'),
Q('בפרשת הפרטת בתי הסוהר (2009) נפסל החוק כי:','אין בחוק יסוד: כבוד האדם פסקת התגברות והחוק פגע בכבוד',['החוק נחקק בפסקת התגברות','החוק נתקבל ללא רוב','החוק לא פגע בזכות'],'בחוק כבוד האדם אין התגברות, ולכן הכנסת אינה יכולה לגבור. המסיחים האחרים אינם נכונים עובדתית.'),
Q('מהי השאלה הראשונה כשבודקים חוק בפסקת התגברות?','האם יש אמירה מפורשת "על אף"',['האם התוכן מידתי','האם החוק נחקק לפני 1992','מה דעת הממשלה'],'בלי האמירה המפורשת, ההתגברות אינה חלה. מידתיות רלוונטית רק בהיעדרה.'),
Q('מה ההבדל בין ההסדר הקנדי להסדר הישראלי?','בקנדה התוקף חמש שנים ובישראל ארבע',['בקנדה ללא הגבלת זמן','בישראל חמש שנים','אין בקנדה כלל'],'בקנדה (ס׳ 33 לצ׳רטר) הפסקה פוקעת אחרי חמש שנים, ובישראל ארבע. שני האחרים שגויים.'),
Q('האם ניתן לחדש חוק שפקע בפסקת התגברות?','כן, בחקיקה חדשה העומדת בתנאי הפסקה',['לא, לעולם','כן, ללא תנאים','כן, בהחלטת הממשלה'],'חידוש מחייב חקיקה חדשה העומדת בתנאים. אין איסור מוחלט, ואין חידוש ללא תנאים או בהחלטת ממשלה.'),
Q('על איזו זכות חלה פסקת ההתגברות?','חופש העיסוק',['כבוד האדם','חופש הביטוי','שוויון'],'היא חלה על חוק יסוד: חופש העיסוק בלבד. כבוד, ביטוי ושוויון אינם חלק מהמנגנון.'),
]
