EXTRA_E={6: ' בנוסף, הפקיעה האוטומטית מחייבת את הכנסת לשוב ולדון בנושא, ולכן אי אפשר לטעון שהחוק נשאר בתוקף מעצמו או הופך לחוק יסוד.', 7: ' ההרמוניה מחייבת קודם כול ניסיון ליישב בין הנורמות, ורק אם הדבר בלתי אפשרי מפעילים כללי הכרעה כמו ספציפי מול כללי.', 9: ' ההבחנה חשובה: ההגבלה היא קריטריון לפגיעה כדין, וההתגברות היא מנגנון עוקף ולא הוראה שמוסיפה מידתיות.', 10: ' טיעון הביקורת הוא ערכי: אם הרוב יכול לגבור על הזכות, ההגנה החוקתית נחלשת, ולכן המתנגדים מדגישים את הסכנה לזכויות המיעוט.', 11: ' זהו טיעון דמוקרטי ולא טיעון נגד הזכויות, שכן הוא מדגיש שהכרעה בנושאים עקרוניים שייכת בסופו של דבר לנבחרי הציבור.', 12: ' ההלכה בעתירה זו היא שבית המשפט בודק את התנאים הפורמליים של הפסקה, ולא עורך שוב בחינת מידתיות מלאה של הפגיעה.', 13: ' במילים אחרות, משהתקיימו התנאים, הפגיעה בחופש העיסוק אינה עילה לפסילה, אך עדיין ייתכנו עילות אחרות כגון פגיעה בשוויון.', 14: ' כלל הספציפי הגובר מבוסס על ההנחה שהמחוקק התכוון להסדר מפורט דווקא, ולכן אין זה נכון שהכללי גובר או שהממשלה מכריעה.', 15: ' בחוק כבוד האדם אין התגברות, ולכן הכנסת אינה יכולה לעקוף פסילה כזו בחוק רגיל, בניגוד לנושא של חופש העיסוק.', 16: ' הבדיקה הפורמלית היא תנאי סף ולכן נעשית לפני כל בחינה מהותית, כי היעדרה מוביל מיד לבחינה בפסקת ההגבלה.', 17: ' ההשוואה הקנדית שימושית בתור דוגמה לפסקה דומה, אך שם הרוב רגיל והתוקף חמש שנים, ולכן ההבדל במספר השנים הוא הנכון.', 18: ' החידוש מחייב קיום מחודש של כל התנאים: אמירה מפורשת, רוב מתאים ותוקף מוגבל חדש, ולכן אין חידוש אוטומטי.', 19: ' הפסקה מוגבלת לזכות אחת בלבד ואינה נוגעת לביטוי, לשוויון או לכבוד, ולכן אין להרחיבה לזכויות אחרות.'}
for _i,_t in EXTRA_E.items(): QS[_i]['e']+=_t
SUM[-1:-1]=['<h3>5.6 האם ניתן לבקר שימוש בהתגברות</h3>', '<p>שאלה פתוחה היא האם בית המשפט רשאי לבקר שימוש בפסקת ההתגברות מעבר לבדיקת התנאים הפורמליים. הגישה המקובלת היא שמשעמדו התנאים, אין עילה לפסול את החוק בשל פגיעה בחופש העיסוק. עם זאת, בפסיקה נשמעו קולות שלפיהם שימוש לרעה בפסקה, למשל חקיקה שחוזרת וממשיכה את ההתגברות בלי שקילה אמיתית או חקיקה פוגענית ביסודות המשטר, עשוי להיבחן במסגרת הדוקטרינה של שימוש לרעה בסמכות. הסוגיה לא הוכרעה סופית, ולכן במבחן עדיף לנסח בזהירות ולהצביע על הצדדים.</p>']

EXTRA_E={}
for _i,_t in EXTRA_E.items(): QS[_i]['e']+=_t
SUM[-1:-1]=['<h3>5.7 מבט השוואתי ופרשני נוסף</h3>', '<p>מעבר להשוואה לקנדה, ראוי להבחין בין התגברות על פסילה שיפוטית קיימת (כמו בפרשת יבוא הבשר, שבה החקיקה באה אחרי הפסיקה) לבין התגברות מראש, שבה החוק נחקק בלי פסיקה קודמת. בשני המקרים התנאים זהים, אך המשמעות הציבורית שונה: התגברות בעקבות פסיקה נתפסת כפולמוס בין הכנסת לבית המשפט, בעוד התגברות מראש נתפסת כהכרעה מדינית מוצהרת. בפרקטיקה השימוש בפסקה נדיר, וזו אחת הסיבות לכך שהיא נתפסת כאמצעי חריג.</p>']
